@@ -1,7 +1,36 @@
-import { useState } from 'react';
+import { useEffect, useState } from 'react';
+
+const NAV_LINKS = [
+  { href: '#board', label: 'Board' },
+  { href: '#activity', label: 'Activity' },
+  { href: '#reports', label: 'Reports' },
+];
+
+function hashToDestination(hash: string) {
+  return NAV_LINKS.some((link) => link.href === hash) ? hash : '';
+}

 export function ResponsiveNav() {
   const [open, setOpen] = useState(false);
+  const [activeHref, setActiveHref] = useState(() =>
+    typeof window === 'undefined' ? '' : hashToDestination(window.location.hash),
+  );
+
+  useEffect(() => {
+    const syncWithHash = () => setActiveHref(hashToDestination(window.location.hash));
+    syncWithHash();
+    window.addEventListener('hashchange', syncWithHash);
+    return () => window.removeEventListener('hashchange', syncWithHash);
+  }, []);
+
+  const handleNavigate = (href: string) => {
+    setActiveHref(href);
+    setOpen(false);
+    if (typeof window !== 'undefined' && window.location.hash !== href) {
+      window.location.hash = href;
+    }
+  };
+
   return (
     <nav className="top-nav" aria-label="Primary navigation">
       <a className="brand" href="#top">RB</a>
@@ -15,8 +44,16 @@ export function ResponsiveNav() {
         Menu
       </button>
       <div id="nav-links" className={`nav-links ${open ? 'open' : ''}`}>
-        <a href="#board">Board</a>
-        <a href="#activity">Activity</a>
+        {NAV_LINKS.map((link) => (
+          <a
+            key={link.href}
+            href={link.href}
+            aria-current={activeHref === link.href ? 'page' : undefined}
+            onClick={() => handleNavigate(link.href)}
+          >
+            {link.label}
+          </a>
+        ))}
       </div>
     </nav>
   );
